Q: WPF MVVM: ComboBox not updating correctly after adding new item A: <pre><code>using Model;
using System.ComponentModel;

namespace ViewModel
{
    public class VMMannschaft : INotifyPropertyChanged
    {
        private Mannschaft mannschaft;

        public VMMannschaft(String nation)
        {
            this.mannschaft = new Mannschaft(nation);
        }

        public String Nation
        {
            get
            {

                return mannschaft.Nation;
            }
        }

        public int Punkte { get =&gt;  mannschaft.Punkte;}

        public int Spiele { get =&gt; mannschaft.Spiele;}

        public event PropertyChangedEventHandler? PropertyChanged;

        public void Sieg()
        {
            mannschaft.Sieg();
            PropertyChanged.Invoke(this,new PropertyChangedEventArgs(nameof(Punkte)));
            PropertyChanged.Invoke(this, new PropertyChangedEventArgs(nameof(Spiele)));
        }

        public void Niederlage()
        {
            mannschaft.Niederlage();
            PropertyChanged.Invoke(this, new PropertyChangedEventArgs(nameof(Spiele)));
        }

        public void Unentschieden()
        {
            mannschaft.Unentschieden();
            PropertyChanged.Invoke(this, new PropertyChangedEventArgs(nameof(Spiele)));
            PropertyChanged.Invoke(this, new PropertyChangedEventArgs(nameof(Punkte)));
        }

        public override string ToString()
        {
            return mannschaft.ToString();
        }
    }
}




