using System.Windows.Input;

namespace ViewModel
{
    public class UserCommand : ICommand
    {
        private Action&lt;object&gt; action;
        public event EventHandler? CanExecuteChanged;

        public UserCommand(Action&lt;object&gt; action)
        {
            this.action = action;
        }

        public bool CanExecute(object? parameter)
        {
            return true;
        }

        public void Execute(object? parameter)
        {
            if (parameter != null)
            {
                action(parameter);
            }
        }
    }
}





using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Text;
using System.Windows.Input;

namespace ViewModel
{
    public class VMMainWindow
    {
        private ObservableCollection&lt;VMMannschaft&gt; mannschaften;
        private ICommand buttonSieg;
        private ICommand buttonNiederlage;
        private ICommand buttonUnentschieden;


        public ObservableCollection&lt;VMMannschaft&gt; Mannschaften { get =&gt; mannschaften; set =&gt; mannschaften = value; }
        public ICommand ButtonSieg { get =&gt; buttonSieg; set =&gt; buttonSieg = value; }
        public ICommand ButtonNiederlage { get =&gt; buttonNiederlage; set =&gt; buttonNiederlage = value; }
        public ICommand ButtonUnentschieden { get =&gt; buttonUnentschieden; set =&gt; buttonUnentschieden = value; }

        public VMMainWindow()
        {
            mannschaften = new ObservableCollection&lt;VMMannschaft&gt;();
            VMMannschaft vmmanschaft = new VMMannschaft(&quot;Germany&quot;);
            mannschaften.Add(vmmanschaft);
            buttonSieg = new UserCommand(new Action&lt;object&gt;(VMMWMannschaftSieg));
            buttonNiederlage = new UserCommand(new Action&lt;object&gt;(VMMWMannschaftNiederlage));
            buttonUnentschieden = new UserCommand(new Action&lt;object&gt;(VMMWMannschaftUnentschieden));
        }

        private void VMMWMannschaftSieg(object parameter)
        {
            VMMannschaft vmmannschaft = (VMMannschaft) parameter;
            vmmannschaft.Sieg();
        }


        private void VMMWMannschaftNiederlage(object parameter)
        {
            VMMannschaft vmmannschaft = (VMMannschaft)parameter;
            vmmannschaft.Niederlage();
        }

        private void VMMWMannschaftUnentschieden(object parameter)
        {
            VMMannschaft vmmannschaft = (VMMannschaft)parameter;
            vmmannschaft.Unentschieden();
        }






    }
}



namespace Model
{
    public class Mannschaft
    {
        private String nation;
        private int spiele;
        private int punkte;

        public Mannschaft(string nation)
        {
            this.nation = nation;

        }

        public string Nation { get =&gt; nation; set =&gt; nation = value; }
        public int Spiele { get =&gt; spiele; set =&gt; spiele = value; }
        public int Punkte { get =&gt; punkte; set =&gt; punkte = value; }

        public void Sieg()
        {
            punkte += 3;
            spiele++;
        }

        public void Niederlage()
        {
            spiele++;
        }

        public void Unentschieden()
        {
            punkte += 1;
            spiele++;
        }

        public override string ToString()
        {
            return $&quot;{nation}&quot;;
        }
    }

}
